INSERT INTO `place_translations` (`place_id`, `language`, `name`, `description`) VALUES
(1,'bg','Национален театър „Марин Сореску“','Основан през 1850 г., театърът носи името на изтъкнатия деец на културата и писател с международна известност Марин Сореску, получено в годините след Революцията от 1989 г.'),
(1,'sr','Narodno pozorište „Marin Sorescu“','Osnovano 1850. godine, pozorište u godinama nakon Revolucije 1989. dobilo je ime po Marinu Soreskuu, kulturnom stvaraocu i piscu svetskog glasa.'),
(3,'bg','Старият град','Очарователни тесни улички, исторически сгради и уютни тераси.'),
(3,'sr','Stari grad','Šarmantne uske uličice, istorijske zgrade i prijatne terase.'),
(4,'bg','Стадион „Йон Облеменко“','Стадионът е открит през 2017 г. и има капацитет от 30 983 места.'),
(4,'sr','Stadion „Jon Oblemenko“','Stadion je otvoren 2017. godine i ima kapacitet od 30.983 mesta.'),
(5,'bg','Парк „Николае Романеску“','Най-големият и най-известният парк в града, обявен за исторически паметник.'),
(5,'sr','Park „Nikolae Romanesku“','Najveći i najpoznatiji park u gradu, proglašen istorijskim spomenikom.'),
(6,'bg','Художествен музей','Помещава се в бившия дворец „Жан Михаил“ и представя значима колекция от румънско и европейско изкуство, включително скулптури на Константин Бранкуш.'),
(6,'sr','Muzej umetnosti','Smešten u nekadašnjoj palati Žana Mihaila, izlaže značajnu kolekciju rumunske i evropske umetnosti, uključujući skulpture Konstantina Brankušija.'),
(7,'bg','Ботаническа градина „Александру Буя“','Университетска ботаническа градина със стотици растителни видове, тропически оранжерии и сенчести алеи – идеална за спокойна разходка.'),
(7,'sr','Botanička bašta „Aleksandru Buja“','Univerzitetska botanička bašta sa stotinama biljnih vrsta, tropskim staklenicima i senovitim stazama, idealna za opuštajuću šetnju.'),
(8,'bg','Катедрала „Свети Димитър“','Внушителна православна катедрала в центъра на града, известна с неовизантийската си архитектура и вътрешните си стенописи.'),
(8,'sr','Katedrala „Sveti Dimitrije“','Impozantna pravoslavna katedrala u centru grada, poznata po neovizantijskoj arhitekturi i unutrašnjim freskama.'),
(9,'bg','Fantasy Park','Увеселителен парк с игри и атракции за всички възрасти, подходящ за семейна разходка.'),
(9,'sr','Fantasy Park','Zabavni park sa igrama i atrakcijama za sve uzraste, odličan za porodični izlet.'),
(10,'bg','Музей на историята и археологията на Олтения','Представя археологически и исторически експонати от региона Олтения – от праисторията до модерната епоха.'),
(10,'sr','Muzej istorije i arheologije Oltenije','Izlaže arheološke i istorijske predmete iz regiona Oltenije, od praistorije do modernog doba.'),
(11,'bg','Площад „Михай Витязул“','Централният площад на Крайова – оживено място за срещи, заобиколено от исторически сгради и тераси.'),
(11,'sr','Trg „Mihai Viteazul“','Centralni trg Krajove, živo mesto okupljanja okruženo istorijskim zgradama i terasama.'),
(12,'bg','Английският парк','Парк, оформен в английски стил, с тихи алеи, буйна зеленина и места за отдих.'),
(12,'sr','Engleski park','Park uređen u engleskom stilu, sa mirnim stazama, bujnim zelenilom i prostorima za odmor.'),
(13,'bg','Педагогически парк','Тихо зелено пространство, обитавано от пауни, идеално за разходки на открито.'),
(13,'sr','Pedagoški park','Mirna zelena oaza u kojoj žive paunovi, idealna za šetnje na otvorenom.'),
(14,'bg','Младежки парк','Най-големият парк за отдих в града, с езеро, спортни площадки и детски площадки.'),
(14,'sr','Park mladosti','Najveći rekreativni park u gradu, sa jezerom, sportskim terenima i dečjim igralištima.');
INSERT INTO `event_translations` (`event_id`, `language`, `location`, `title`, `description`, `details`) VALUES
(5,'bg','Кино „Патрия“, Крайова','Trooper','Trooper отбелязва 30 години на сцената с голямо юбилейно турне, което ще премине през не по-малко от 28 града.','https://zilesinopti.ro/evenimente/trooper-cinema-patria-craiova-2/'),
(5,'sr','Bioskop „Patria“, Krajova','Trooper','Trooper obeležava 30 godina rada velikom jubilarnom turnejom koja će obuhvatiti čak 28 gradova.','https://zilesinopti.ro/evenimente/trooper-cinema-patria-craiova-2/'),
(6,'bg','Национален театър „Марин Сореску“','Визионерите','Пазете мозъка си активен, ума си ясен и живота си в собствените си ръце. Живеем живота, който умът и мозъкът ни могат да поддържат.','https://zilesinopti.ro/evenimente/vizionarii-teatrul-national-craiova/'),
(6,'sr','Narodno pozorište „Marin Sorescu“','Vizionari','Održite mozak aktivnim, um bistrim, a život u svojim rukama. Živimo onaj život koji naš um i mozak mogu da podnesu.','https://zilesinopti.ro/evenimente/vizionarii-teatrul-national-craiova/'),
(7,'bg','Национален театър „Марин Сореску“','Щефан Беника','Щефан Беника разказва своята история в националното турне „Моята история“.','https://zilesinopti.ro/evenimente/stefan-banica-teatrul-national-craiova/'),
(7,'sr','Narodno pozorište „Marin Sorescu“','Štefan Banika','Štefan Banika priča svoju priču na nacionalnoj turneji „Moja priča“.','https://zilesinopti.ro/evenimente/stefan-banica-teatrul-national-craiova/'),
(8,'bg','Национален театър „Марин Сореску“','Ромео и Жулиета','Най-известната любовна история в света се завръща в зрелищна постановка на режисьора Тома Енаке, създател на успешния спектакъл „Изгубеното писмо“, реализирана със същия артистичен екип и продуцент, спечелили признанието на публиката.','https://zilesinopti.ro/evenimente/romeo-si-julieta-craiova/'),
(8,'sr','Narodno pozorište „Marin Sorescu“','Romeo i Julija','Najpoznatija ljubavna priča na svetu vraća se u spektakularnoj postavci reditelja Tome Enakea, autora uspešne predstave „Izgubljeno pismo“, ostvarenoj sa istim umetničkim timom i producentom koji su osvojili publiku.','https://zilesinopti.ro/evenimente/romeo-si-julieta-craiova/'),
(9,'bg','Филхармония „Олтения“, Крайова','Клетниците','Монументална история за падение и възраждане, вина и прошка, лъжа и истина, любов и революция.','https://zilesinopti.ro/evenimente/mizerabilii-filarmonica-oltenia-craiova/'),
(9,'sr','Filharmonija „Oltenija“, Krajova','Jadnici','Monumentalna priča o padu i iskupljenju, krivici i oproštaju, laži i istini, ljubavi i revoluciji.','https://zilesinopti.ro/evenimente/mizerabilii-filarmonica-oltenia-craiova/'),
(10,'bg','Национален театър „Марин Сореску“','Парижката Света Богородица','Theater du Soleil Entertainment представя нова динамична продукция, изпълнена с цвят и емоция. „Парижката Света Богородица“ майсторски пресъздава една от най-старите истории в света под формата на мюзикъл на живо, в който героите оживяват на сцената.','https://zilesinopti.ro/evenimente/cocosatul-de-la-notre-dame-teatrul-national-marin-sorescu/'),
(10,'sr','Narodno pozorište „Marin Sorescu“','Grbavac Bogorodičine crkve','Theater du Soleil Entertainment predstavlja novu dinamičnu produkciju punu boja i emocija. „Grbavac Bogorodičine crkve“ majstorski oživljava jednu od najstarijih priča na svetu kroz mjuzikl uživo, u kojem likovi oživljavaju na sceni.','https://zilesinopti.ro/evenimente/cocosatul-de-la-notre-dame-teatrul-national-marin-sorescu/'),
(11,'bg','Национален театър „Марин Сореску“','Аурелиан Темишан','Концерт на живо, изпълнен с емоция, елегантност и музика от най-високо качество.','https://zilesinopti.ro/evenimente/aurelian-temisan-teatrul-craiova/'),
(11,'sr','Narodno pozorište „Marin Sorescu“','Aurelijan Temišan','Nastup uživo pun emocija, elegancije i muzike najvišeg kvaliteta.','https://zilesinopti.ro/evenimente/aurelian-temisan-teatrul-craiova/'),
(12,'bg','Филхармония „Олтения“, Крайова','Мирабела Дауер и Габриел Доробанцу','Сърдечен концерт, изпълнен с емоция и носталгия, събира на една сцена двама от най-обичаните изпълнители на румънската музика: Мирабела Дауер и Габриел Доробанцу.','https://zilesinopti.ro/evenimente/mirabela-dauer-gabriel-dorobantu-craiova/'),
(12,'sr','Filharmonija „Oltenija“, Krajova','Mirabela Dauer i Gabrijel Dorobancu','Emotivan koncert pun nostalgije okuplja na istoj sceni dvoje najomiljenijih izvođača rumunske muzike: Mirabelu Dauer i Gabrijela Dorobancua.','https://zilesinopti.ro/evenimente/mirabela-dauer-gabriel-dorobantu-craiova/'),
(13,'bg','Студентски дом на културата, Крайова','The Evolution of Magic','Модерно театрално магическо шоу, което съчетава илюзии, ментализъм, разказване на истории, взаимодействие с публиката и визуална магия в цялостно театрално преживяване.','https://zilesinopti.ro/evenimente/the-evolution-of-magic-craiova/'),
(13,'sr','Studentski dom kulture, Krajova','The Evolution of Magic','Moderni pozorišni mađioničarski šou koji spaja iluzije, mentalizam, pripovedanje, interakciju sa publikom i vizuelnu magiju u celovito pozorišno iskustvo.','https://zilesinopti.ro/evenimente/the-evolution-of-magic-craiova/'),
(14,'bg','Филхармония „Олтения“','Покана за валс','Вечерта на 12 ноември, в рамките на сезона Musical Extravaganza, светлините ще озарят елегантността на една отминала епоха, а Филхармония „Олтения“ ще се превърне в сцена на приказен бал.','https://zilesinopti.ro/evenimente/invitatie-la-vals-filarmonica-oltenia/'),
(14,'sr','Filharmonija „Oltenija“','Poziv na valcer','Uveče 12. novembra, u okviru sezone Musical Extravaganza, svetla će obasjati eleganciju jednog minulog doba, a Filharmonija „Oltenija“ postaće pozornica bajkovitog bala.','https://zilesinopti.ro/evenimente/invitatie-la-vals-filarmonica-oltenia/'),
(22,'bg','Булевард „Калеа Унирий“, Крайова','Puppets Occupy Street 2026 – Stardust Edition','Международният фестивал на уличния и кукления театър се завръща в Крайова за своето 13-о издание с артисти от 16 държави: спектакли, безплатни работилници, концерти и инсталации, с откриващ парад по „Калеа Унирий“.','https://craiovalive.ro/eveniment/puppets-occupy-street-2026-stardust-edition/2026-08-26/'),
(22,'sr','Bulevar Kalea Unirij, Krajova','Puppets Occupy Street 2026 – Stardust Edition','Međunarodni festival uličnog i lutkarskog pozorišta vraća se u Krajovu na svoje 13. izdanje, sa umetnicima iz 16 zemalja: predstave, besplatne radionice, koncerti i instalacije, uz paradu otvaranja na Kalea Unirij.','https://craiovalive.ro/eveniment/puppets-occupy-street-2026-stardust-edition/2026-08-26/'),
(23,'bg','Филхармония „Олтения“ и градината на Окръжната библиотека „Александру и Аристия Аман“','Craiova Jazz Festival','Три джаз вечери с Ирина Сърбу, Сорин Злат, Биг бенда на Радио Румъния, Jazzappella, Ethnotic Project и много други. Събитията се провеждат от 12 до 14 септември, с начало от 18:00 ч.',NULL),
(23,'sr','Filharmonija „Oltenija“ i bašta Okružne biblioteke „Aleksandru i Aristija Aman“','Craiova Jazz Festival','Tri džez večeri sa Irinom Sarbu, Sorinom Zlatom, Big bendom Radio Rumunije, Jazzappella, Ethnotic Project i mnogim drugima. Događaji se održavaju od 12. do 14. septembra, sa početkom u 18:00.',NULL),
(24,'bg','Национален театър „Марин Сореску“, площад „Уилям Шекспир“, парк „Николае Романеску“, Electroputere Mall и други места в Крайова','CONNECT – Common Ground','Пет дни съвременен танц, пърформанси, работилници, прожекции и изложби, които превръщат целия град в истинска сцена. Събитието се провежда от 9 до 13 септември.',NULL),
(24,'sr','Narodno pozorište „Marin Sorescu“, Trg Vilijama Šekspira, park „Nikolae Romanesku“, Electroputere Mall i druga mesta u Krajovi','CONNECT – Common Ground','Pet dana savremene igre, performansa, radionica, projekcija i izložbi koje ceo grad pretvaraju u pravu pozornicu. Događaj traje od 9. do 13. septembra.',NULL),
(25,'bg','Къща „Диану“ – Музей на румънската книга и емиграция','InstaCraiova, The Festival','11-ото издание идва с темата „Аналогово срещу дигитално“ и обединява фотография, музика, работилници, изложби и конференции. Провежда се от 11 до 13 септември.',NULL),
(25,'sr','Kuća Dianu – Muzej rumunske knjige i egzila','InstaCraiova, The Festival','11. izdanje stiže sa temom „Analogno protiv digitalnog“ i okuplja fotografiju, muziku, radionice, izložbe i konferencije. Održava se od 11. do 13. septembra.',NULL),
(26,'bg','Ramada Plaza','Romania Grand Prix – Craiova','Крайова става столица на ускорения шах! Близо 250 шахматисти от 16 държави са записани за последния етап от веригата. Провежда се на 12–13 септември.',NULL),
(26,'sr','Ramada Plaza','Romania Grand Prix – Craiova','Krajova postaje prestonica brzog šaha! Skoro 250 igrača iz 16 zemalja prijavljeno je za poslednju etapu turnira. Održava se 12–13. septembra.',NULL),
(27,'bg','Летен театър – парк „Николае Романеску“','RoPOT in the Park','Първата концепция, която довежда хаус музиката в Летния театър в парк „Николае Романеску“. Провежда се на 12 септември от 15:00 до 23:00 ч.',NULL),
(27,'sr','Letnja pozornica – park „Nikolae Romanesku“','RoPOT in the Park','Prvi koncept koji donosi haus muziku na Letnju pozornicu u parku „Nikolae Romanesku“. Održava se 12. septembra, od 15:00 do 23:00.',NULL),
(28,'bg','Площад „Михай Витязул“','Urban Playfield','Крайова, хайде да играем! Градът се превръща в истинска площадка за игра за цялото семейство – два дни, изпълнени с движение, добро настроение и спортни занимания за всички възрасти. Провежда се на 19–20 септември.',NULL),
(28,'sr','Trg „Mihai Viteazul“','Urban Playfield','Krajova, hajde da se igramo! Grad se pretvara u pravo igralište za celu porodicu, sa dva dana punih pokreta, dobrog raspoloženja i sportskih aktivnosti za sve uzraste. Održava se 19–20. septembra.',NULL),
(29,'bg','Многофункционална зала „Поливалента“','IntenCity Festival – 5-о издание','Крайова отново ще вибрира! Тазгодишното издание подготвя една съвсем специална среща – Puya Urban Simfonic на сцената на зала „Поливалента“ в Крайова. Провежда се на 25–26 септември.',NULL),
(29,'sr','Polivalentna dvorana','IntenCity Festival – 5. izdanje','Krajova će ponovo vibrirati! Ovogodišnje izdanje donosi sasvim poseban susret – Puya Urban Simfonic na sceni Polivalentne dvorane u Krajovi. Održava se 25–26. septembra.',NULL);
